import tarfile
import subprocess

def solve(primary: str, comparison: str):
    def get_paths(archive_path, member_filter):
        try:
            with tarfile.open(archive_path, 'r', encoding='utf-8', errors='replace') as tar:
                paths = set()
                for member in tar.getmembers():
                    if member_filter(member):
                        path = member.name.rstrip('/')
                        if path:
                            first_component = path.split('/', 1)[0]
                            paths.add(first_component)
                return paths
        except Exception as e:
            raise RuntimeError(f"Failed to read archive {archive_path}: {e}")

    primary_set = get_paths(primary, lambda m: m.isfile())
    comparison_set = get_paths(comparison, lambda m: m.issym() or m.islnk())

    result = sorted(comparison_set - primary_set)
    return result
